files={'config/baseline.json': {'text': '{\r\n  "scene": "/root/gpufree-data/IsaacSim_Asset/combine_stage/combine_scene_18_terrain_fisheye_mesh.usda",\r\n  "scene_sha256": "e44ff38c21caaaccf20aa44a9b834e33d7109407e737df27198a63ad95e9fb79",\r\n  "robot": "/World/Excavator",\r\n  "physics_hz": 60,\r\n  "warmup_frames": 8,\r\n  "measure_frames": 300,\r\n  "expected_lidars": 13,\r\n  "expected_cameras": 4,\r\n  "ros_domain_id": 196,\r\n  "render_mode": "RealTimePathTracing",\r\n  "dlss_mode": 2,\r\n  "aa_mode": 3,\r\n  "multi_tick": false,\r\n  "mode": "record",\r\n  "motion": "moving",\r\n  "trajectory": "/root/gpufree-data/semantic/output/sensor_visualizer/v06/benchmarks/1791604257379431843_v05/input_trajectory/states.jsonl",\r\n  "trace": false,\r\n  "schedule": "frozen",\r\n  "subframes": 18,\r\n  "timeout_s": 7200,\r\n  "output_root": "/root/gpufree-data/semantic/output/native_scene18_capture_005",\r\n  "experiment": "trajectory",\r\n  "warm_subframes": 16,\r\n  "formal_subframes": 2,\r\n  "pt_spp": 32,\r\n  "pt_total_spp": 1024,\r\n  "pt_bounces": 8,\r\n  "capture_on_play_during_groups": false,\r\n  "pause_after_step": false,\r\n  "freeze_method": "autoupdate",\r\n  "bypass_native_simulation_gate": false,\r\n  "gate_products_between_groups": false,\r\n  "export_quality_images": false,\r\n  "reset_pt_per_frame": true,\r\n  "continuous_basic_writer": true,\r\n  "native_preview_initialization": false,\r\n  "group_interval_s": 0.1,\r\n  "group_advance_updates": 6\r\n}\r\n', 'sha256': '74666b04c91370f1407dfba00971353c11afd9eb847e6b0cc6f74380e6418921'}, 'tools/validate_bag.py': {'text': '"""Post-run ROS standard decoding; never on the capture path."""\r\nimport collections,json,math,struct,sys\r\nfrom pathlib import Path\r\nimport rosbag2_py\r\nimport numpy as np\r\nfrom rclpy.serialization import deserialize_message\r\nfrom rosidl_runtime_py.utilities import get_message\r\n\r\ndef validate(directory):\r\n    out=Path(directory);manifest=json.loads((out/\'sensor_manifest.json\').read_text());sensors=manifest[\'sensors\']\r\n    reader=rosbag2_py.SequentialReader();reader.open(rosbag2_py.StorageOptions(uri=str(out/\'bag\'),storage_id=\'mcap\'),rosbag2_py.ConverterOptions(\'\',\'\'))\r\n    topic_types={t.name:t.type for t in reader.get_all_topics_and_types()}\r\n    types={t:get_message(v) for t,v in topic_types.items()};stats={};errors=[];tf_edges=set();camera_calibration={};clock_stamps=set()\r\n    spec=json.loads((out/\'spec.json\').read_text());warnings=[]\r\n    expected={s[\'topic\'] for s in sensors}|{s[\'info_topic\'] for s in sensors if s[\'kind\']==\'camera\'}|{\'/tf\',\'/clock\',\'/joint_states\'}\r\n    mapping={s[\'topic\']:s for s in sensors}\r\n    info_mapping={s[\'info_topic\']:s for s in sensors if s[\'kind\']==\'camera\'}\r\n    first_images={};tf_latest={};tf_ranges={};stamp_sets={};measurement_counts=collections.Counter();joint_ranges={};measurement_images={}\r\n    window=json.loads((out/\'engine_result.json\').read_text())\r\n    begin_ns=round(window[\'simulation_start_s\']*1e9);end_ns=round(window[\'simulation_end_s\']*1e9)\r\n    while reader.has_next():\r\n        topic,data,bag_time=reader.read_next();msg=deserialize_message(data,types[topic])\r\n        st=stats.setdefault(topic,{\'type\':topic_types[topic],\'messages\':0,\'bytes\':0,\'header_times\':[],\'bag_first_ns\':bag_time,\'bag_last_ns\':bag_time,\'frames\':set()})\r\n        st[\'messages\']+=1;st[\'bytes\']+=len(data);st[\'bag_last_ns\']=bag_time\r\n        header=getattr(msg,\'header\',None)\r\n        if header:\r\n            stamp=header.stamp.sec*10**9+header.stamp.nanosec;st[\'header_times\'].append(stamp);st[\'frames\'].add(header.frame_id)\r\n            stamp_sets.setdefault(topic,set()).add(stamp)\r\n            if begin_ns<stamp<=end_ns:measurement_counts[topic]+=1\r\n        if topic==\'/clock\':clock_stamps.add(msg.clock.sec*10**9+msg.clock.nanosec)\r\n        elif topic==\'/joint_states\':\r\n            for name,pos in zip(msg.name,msg.position):\r\n                interval=joint_ranges.setdefault(name,[pos,pos]);interval[0]=min(interval[0],pos);interval[1]=max(interval[1],pos)\r\n        elif topic==\'/tf\':\r\n            for tr in msg.transforms:\r\n                tf_edges.add((tr.header.frame_id,tr.child_frame_id));tf_latest[tr.child_frame_id]=tr\r\n                xyz=np.array([tr.transform.translation.x,tr.transform.translation.y,tr.transform.translation.z])\r\n                interval=tf_ranges.setdefault(tr.child_frame_id,[xyz.copy(),xyz.copy()])\r\n                interval[0]=np.minimum(interval[0],xyz);interval[1]=np.maximum(interval[1],xyz)\r\n        elif topic in mapping:\r\n            s=mapping[topic]\r\n            if header.frame_id!=s[\'frame_id\']:errors.append(\'Unexpected frame_id \'+topic)\r\n            if s[\'kind\']==\'camera\':\r\n                w,h=s[\'size\'];channels=3 if msg.encoding==\'rgb8\' else 4 if msg.encoding==\'rgba8\' else None\r\n                if (msg.width,msg.height)!=(w,h) or channels is None or len(msg.data)!=msg.step*msg.height:errors.append(\'Invalid image \'+topic)\r\n                st[\'image_encoding\']=msg.encoding;st[\'resolution\']=[msg.width,msg.height]\r\n                if begin_ns<stamp<=end_ns:measurement_images[topic]=(bytes(msg.data),channels,w,h,s[\'id\'])\r\n                if topic not in first_images:\r\n                    first_images[topic]=True\r\n                    try:\r\n                        from PIL import Image\r\n                        Image.frombytes(\'RGB\' if channels==3 else \'RGBA\',(w,h),bytes(msg.data)).convert(\'RGB\').save(out/(s[\'id\']+\'_first.png\'))\r\n                    except ImportError:pass\r\n            else:\r\n                fields={f.name:f for f in msg.fields};st[\'point_fields\']=[{\'name\':f.name,\'offset\':f.offset,\'datatype\':f.datatype,\'count\':f.count} for f in msg.fields]\r\n                count=msg.width*msg.height;st.setdefault(\'point_counts\',[]).append(count)\r\n                if not all(k in fields for k in (\'x\',\'y\',\'z\')) or len(msg.data)!=msg.row_step*msg.height:errors.append(\'Invalid cloud layout \'+topic)\r\n                elif count:\r\n                    offsets=[fields[n].offset for n in (\'x\',\'y\',\'z\')];endian=\'>\' if msg.is_bigendian else \'<\'\r\n                    if any(fields[n].datatype!=7 for n in (\'x\',\'y\',\'z\')):raise RuntimeError(\'Unexpected native XYZ type\')\r\n                    finite=np.ones((msg.height,msg.width),dtype=bool)\r\n                    for off in offsets:\r\n                        values=np.ndarray((msg.height,msg.width),dtype=endian+\'f4\',buffer=msg.data,\r\n                                          offset=off,strides=(msg.row_step,msg.point_step))\r\n                        finite &= np.isfinite(values)\r\n                    bad=int((~finite).sum())\r\n                    st[\'nonfinite_xyz\']=st.get(\'nonfinite_xyz\',0)+bad\r\n                    if bad:errors.append(\'Nonfinite cloud \'+topic)\r\n        elif topic in info_mapping:\r\n            s=info_mapping[topic];c=s[\'calibration\'];expected_d=[c[n] for n in [\'k1\',\'k2\',\'k3\',\'k4\']]\r\n            actual={\'width\':msg.width,\'height\':msg.height,\'model\':msg.distortion_model,\'k\':list(msg.k),\'d\':list(msg.d)}\r\n            camera_calibration[topic]=actual\r\n            if msg.distortion_model!=\'equidistant\' or len(msg.d)!=4 or max(abs(a-b) for a,b in zip(msg.d,expected_d))>1e-6:errors.append(\'Fisheye distortion mismatch \'+topic)\r\n            for idx,n in [(0,\'fx\'),(4,\'fy\'),(2,\'cx\'),(5,\'cy\')]:\r\n                if abs(msg.k[idx]-c[n])>1e-3:errors.append(\'Fisheye intrinsics mismatch \'+topic+\' \'+n)\r\n    for topic in sorted(expected):\r\n        if stats.get(topic,{}).get(\'messages\',0)==0:errors.append(\'Missing topic data \'+topic)\r\n    for topic,st in stats.items():\r\n        times=st.pop(\'header_times\');st[\'frames\']=sorted(st[\'frames\'])\r\n        if times:\r\n            st[\'header_first_ns\']=min(times);st[\'header_last_ns\']=max(times)\r\n            st[\'duplicate_stamps\']=len(times)-len(set(times));st[\'backward_stamps\']=sum(b<a for a,b in zip(times,times[1:]))\r\n            span=(max(times)-min(times))/1e9;st[\'effective_sim_hz\']=(len(times)-1)/span if span else None\r\n            st[\'stamps_absent_from_clock\']=sum(t not in clock_stamps for t in times)\r\n            if st[\'backward_stamps\']:errors.append(\'Backward sensor stamps \'+topic)\r\n            if st[\'duplicate_stamps\']:warnings.append(\'Repeated native header stamps \'+topic)\r\n        counts=st.pop(\'point_counts\',[])\r\n        if counts:st[\'points\']={\'min\':min(counts),\'max\':max(counts),\'mean\':sum(counts)/len(counts)}\r\n    wanted_frames={s[\'frame_id\'] for s in sensors}|{\'swing_coordinate\'}\r\n    missing_tf=wanted_frames-{c for p,c in tf_edges}\r\n    if missing_tf:errors.append(\'TF missing sensor/root frames: \'+str(sorted(missing_tf)))\r\n    tf_comparison={}\r\n    expected_path=out/\'expected_final_transforms.json\'\r\n    if expected_path.exists():\r\n        for child,value in json.loads(expected_path.read_text()).items():\r\n            tr=tf_latest.get(child)\r\n            if tr is None:continue\r\n            q=tr.transform.rotation;t=tr.transform.translation\r\n            actual_q=np.array([q.x,q.y,q.z,q.w]);wanted_q=np.array(value[\'quaternion_xyzw\'])\r\n            translation_error=float(np.linalg.norm(np.array([t.x,t.y,t.z])-np.array(value[\'translation\'])))\r\n            rotation_error=float(2*math.acos(min(1.,abs(float(np.dot(actual_q,wanted_q))))))\r\n            tf_comparison[child]={\'translation_error_m\':translation_error,\'rotation_error_rad\':rotation_error,\r\n              \'translation_min\':tf_ranges[child][0].tolist(),\'translation_max\':tf_ranges[child][1].tolist()}\r\n            if translation_error>1e-3 or rotation_error>1e-3:errors.append(\'Final TF disagrees with USD \'+child)\r\n    sensor_sets=[stamp_sets.get(s[\'topic\'],set()) for s in sensors]\r\n    common_stamps=set.intersection(*sensor_sets) if sensor_sets else set()\r\n    if window.get(\'publication_tail_updates\') and not spec[\'multi_tick\']:\r\n        for s in sensors:\r\n            if measurement_counts[s[\'topic\']]!=window[\'frames\']:errors.append(\'Measurement message count differs from native frame count \'+s[\'topic\'])\r\n    if spec[\'schedule\']==\'frozen\':warnings.append(\'Per-group frozen equivalence is checked separately by validate_groups.py; native extra messages remain in the bag.\')\r\n    for raw,channels,w,h,sid in measurement_images.values():\r\n        try:\r\n            from PIL import Image\r\n            Image.frombytes(\'RGB\' if channels==3 else \'RGBA\',(w,h),raw).convert(\'RGB\').save(out/(sid+\'_measurement_last.png\'))\r\n        except ImportError:pass\r\n    result={\'ok\':not errors,\'errors\':sorted(set(errors)),\'warnings\':warnings,\'topics\':stats,\'expected_topics\':sorted(expected),\r\n         \'tf_edges\':sorted([list(e) for e in tf_edges]),\'camera_calibration\':camera_calibration,\r\n         \'tf_final_comparison\':tf_comparison,\'measurement_topic_counts\':dict(measurement_counts),\r\n         \'all_sensor_common_stamps\':len(common_stamps),\r\n         \'joint_ranges_rad\':joint_ranges,\r\n         \'mcap_files\':[{\'name\':p.name,\'bytes\':p.stat().st_size} for p in (out/\'bag\').glob(\'*.mcap\')],\r\n         \'limits\':[\'Standard streaming topics are independent, not custom synchronized groups.\',\r\n           \'Camera info and sensor headers are checked; bag receive timestamps need not equal sensor acquisition timestamps.\',\r\n           \'Finite XYZ and TF connectivity do not prove identical old-project pose or 3DGS physical alignment.\']}\r\n    (out/\'validation.json\').write_text(json.dumps(result,indent=2));return result\r\nif __name__==\'__main__\':\r\n    r=validate(sys.argv[1]);print(json.dumps({\'ok\':r[\'ok\'],\'errors\':r[\'errors\'],\'topics\':len(r[\'topics\'])}));raise SystemExit(0 if r[\'ok\'] else 1)\r\n', 'sha256': '7f5c40722c31584dd8bd03275595175b7e7914426ecdab15b61cfb83b80a3c99'}, 'tools/validate_groups.py': {'text': '"""Strict post-run group validation: native stamps AND matching current RGB bytes."""\r\nimport collections,hashlib,json,sys,math\r\nfrom pathlib import Path\r\nimport numpy as np\r\nimport rosbag2_py\r\nfrom rclpy.serialization import deserialize_message\r\nfrom rosidl_runtime_py.utilities import get_message\r\n\r\ndef main(directory):\r\n out=Path(directory);groups=[json.loads(l) for l in (out/\'groups.jsonl\').read_text().splitlines()]\r\n sensors=json.loads((out/\'sensor_manifest.json\').read_text())[\'sensors\'];mapping={s[\'topic\']:s for s in sensors}\r\n expected=set(mapping)|{s[\'info_topic\'] for s in sensors if s[\'kind\']==\'camera\'}|{\'/joint_states\'}\r\n reader=rosbag2_py.SequentialReader();reader.open(rosbag2_py.StorageOptions(uri=str(out/\'bag\'),storage_id=\'mcap\'),rosbag2_py.ConverterOptions(\'\',\'\'))\r\n types={t.name:get_message(t.type) for t in reader.get_all_topics_and_types()};by_stamp=collections.defaultdict(collections.Counter)\r\n hashes=collections.defaultdict(lambda:collections.defaultdict(set));joints=collections.defaultdict(list);bounds=collections.defaultdict(lambda:[None,None]);tf_stamps=collections.Counter();transforms=collections.defaultdict(dict);xyz_hashes=collections.defaultdict(lambda:collections.defaultdict(set))\r\n while reader.has_next():\r\n  topic,data,t=reader.read_next();msg=deserialize_message(data,types[topic]);h=getattr(msg,\'header\',None)\r\n  if h:\r\n   stamp=h.stamp.sec*10**9+h.stamp.nanosec;by_stamp[stamp][topic]+=1\r\n   limits=bounds[topic];limits[0]=stamp if limits[0] is None else min(limits[0],stamp);limits[1]=stamp if limits[1] is None else max(limits[1],stamp)\r\n   if topic in mapping and mapping[topic][\'kind\']==\'camera\':\r\n    channels=3 if msg.encoding==\'rgb8\' else 4\r\n    rgb=np.ndarray((msg.height,msg.width,channels),dtype=\'u1\',buffer=msg.data,strides=(msg.step,channels,1))[:,:,:3]\r\n    hashes[stamp][topic].add(hashlib.sha256(np.ascontiguousarray(rgb).tobytes()).hexdigest())\r\n   if topic in mapping and mapping[topic][\'kind\']==\'lidar\':\r\n    fields={f.name:f for f in msg.fields};xyz=np.empty((msg.height,msg.width,3),dtype=\'<f4\')\r\n    for i,name in enumerate((\'x\',\'y\',\'z\')):\r\n     f=fields[name]\r\n     if f.datatype!=7:raise RuntimeError(\'Unsupported native XYZ field \'+name)\r\n     xyz[:,:,i]=np.ndarray((msg.height,msg.width),dtype=\'>f4\' if msg.is_bigendian else \'<f4\',buffer=msg.data,offset=f.offset,strides=(msg.row_step,msg.point_step))\r\n    xyz_hashes[stamp][topic].add(hashlib.sha256(xyz.tobytes()).hexdigest())\r\n   if topic==\'/joint_states\':joints[stamp].append(dict(zip(msg.name,msg.position)))\r\n  elif topic==\'/tf\':\r\n   for tr in msg.transforms:\r\n    stamp=tr.header.stamp.sec*10**9+tr.header.stamp.nanosec;tf_stamps[stamp]+=1\r\n    t=tr.transform.translation;q=tr.transform.rotation\r\n    transforms[stamp][tr.child_frame_id]={\'parent\':tr.header.frame_id,\'translation\':[t.x,t.y,t.z],\'quaternion_xyzw\':[q.x,q.y,q.z,q.w]}\r\n results=[];errors=[]\r\n for g in groups:\r\n  stamp=round(g[\'native_time_s\']*1e9);candidate=[k for k in by_stamp if abs(k-stamp)<=2]\r\n  counts=collections.Counter();actual_hashes=collections.defaultdict(set)\r\n  for k in candidate:\r\n   counts.update(by_stamp[k])\r\n   for topic,values in hashes[k].items():actual_hashes[topic].update(values)\r\n  missing=sorted(expected-set(counts));mismatch=[];lidar_mismatch=[]\r\n  for topic,im in g[\'images\'].items():\r\n   if im[\'sha256\'] not in actual_hashes[topic]:mismatch.append(topic)\r\n   if im[\'camera_pose_max_abs_error\']>2e-3:errors.append(f"Group {g[\'group\']} rendered camera pose mismatch {topic}")\r\n  for topic,point in g.get(\'lidars\',{}).items():\r\n   if \'observation_error\' in point:errors.append(f"Group {g[\'group\']} native LiDAR observer failed {topic}");continue\r\n   actual=set().union(*(xyz_hashes[k][topic] for k in candidate))\r\n   if point[\'sha256_xyz\'] not in actual:lidar_mismatch.append(topic)\r\n   if point[\'render_pose_max_abs_error\']>2e-3:errors.append(f"Group {g[\'group\']} rendered LiDAR pose mismatch {topic}")\r\n  if lidar_mismatch:errors.append(f"Group {g[\'group\']} MCAP/current XYZ hash mismatch: {lidar_mismatch}")\r\n  if missing:errors.append(f"Group {g[\'group\']} missing fresh messages: {missing}")\r\n  if mismatch:errors.append(f"Group {g[\'group\']} MCAP/current RGB hash mismatch: {mismatch}")\r\n  found=[j for k in candidate for j in joints[k]]\r\n  joint_error=min((max(abs(j.get(n,float(\'inf\'))-v) for n,v in g[\'joints_rad\'].items()) for j in found),default=float(\'inf\'))\r\n  if joint_error>1e-3:errors.append(f"Group {g[\'group\']} joint state mismatch")\r\n  if not any(abs(k-stamp)<=2 for k in tf_stamps):errors.append(f"Group {g[\'group\']} missing TF at frozen stamp")\r\n  actual_tf={child:tr for k,values in transforms.items() if abs(k-stamp)<=2 for child,tr in values.items()};tf_errors=[]\r\n  for child,want in g.get(\'expected_tf\',{}).items():\r\n   got=actual_tf.get(child)\r\n   if got is None or got[\'parent\']!=want[\'parent\'] or max(abs(x-y) for x,y in zip(got[\'translation\'],want[\'translation\']))>2e-3 or abs(np.dot(got[\'quaternion_xyzw\'],want[\'quaternion_xyzw\']))<1-2e-5:tf_errors.append(child)\r\n  if tf_errors:errors.append(f"Group {g[\'group\']} numeric TF mismatch: {tf_errors}")\r\n  results.append({\'group\':g[\'group\'],\'case\':g[\'case\'],\'expected_stamp_ns\':stamp,\'missing\':missing,\'matching_image_bytes\':not mismatch,\'matching_xyz_bytes\':not lidar_mismatch,\'tf_errors\':tf_errors,\'counts\':dict(counts),\'joint_error_rad\':joint_error})\r\n if not groups:errors.append(\'No completed groups\')\r\n if len({round(g[\'native_time_s\']*1e9) for g in groups})!=len(groups):errors.append(\'Cross-group native stamps are not unique\')\r\n spec=json.loads((out/\'spec.json\').read_text())\r\n if len(groups)!=spec[\'measure_frames\']:errors.append(\'Requested trajectory group count not completed\')\r\n if any(g.get(\'root_target_max_abs_error\',float(\'inf\'))>1e-4 or g.get(\'joint_target_max_abs_error_rad\',float(\'inf\'))>1e-4 for g in groups):errors.append(\'Trajectory target differs from captured pose\')\r\n budget_results=[]\r\n if spec.get(\'experiment\')==\'continuous_pt\':\r\n  from PIL import Image\r\n  if len(groups)!=spec[\'measure_frames\']:errors.append(\'Incomplete requested continuous logical frame count\')\r\n  for g in groups:\r\n   total=spec[\'pt_total_spp\'];spp=spec[\'pt_spp\'];s=g[\'settings\'];png_errors=[]\r\n   budget=(g.get(\'sdk_subframes_at_capture\')==total//spp and g.get(\'accumulation_reset\') is True and\r\n    s.get(\'/rtx/rendermode\')==\'PathTracing\' and s.get(\'/rtx/pathtracing/totalSpp\')==total and\r\n    s.get(\'/rtx/pathtracing/spp\')==spp and s.get(\'/rtx/pathtracing/adaptiveSampling/enabled\') is False and\r\n    s.get(\'/rtx/resetPtAccumOnAnimTimeChange\') is True)\r\n   if not budget:errors.append(f"Group {g[\'group\']} per-image high-SPP completion not verified")\r\n   for sensor in sensors:\r\n    if sensor[\'kind\']!=\'camera\':continue\r\n    paths=[p for p in (out/\'native_basic_images\').rglob(f"rgb_{g[\'group\']:04d}.png") if any(\'NativeBaseline_\'+sensor[\'id\'] in part for part in p.parts)]\r\n    if len(paths)!=1:png_errors.append(sensor[\'id\']+\': expected one native BasicWriter reference image\');continue\r\n    rgb=np.asarray(Image.open(paths[0]).convert(\'RGB\'))\r\n    if hashlib.sha256(np.ascontiguousarray(rgb).tobytes()).hexdigest()!=g[\'images\'][sensor[\'topic\']][\'sha256\']:\r\n     png_errors.append(sensor[\'id\']+\': BasicWriter/current-observer bytes differ\')\r\n   if png_errors:errors.append(f"Group {g[\'group\']} native final-capture PNG mismatch {png_errors}")\r\n   budget_results.append({\'group\':g[\'group\'],\'budget_completion\':budget,\'basic_writer_image_errors\':png_errors})\r\n result={\'ok\':not errors,\'errors\':errors,\'groups\':results,\'topic_stamp_bounds\':dict(bounds),\r\n  \'limits\':[\'Image byte equality ties MCAP to observed output, not real-world ground truth.\',\'Requested PT sample settings do not prove hardware executed exactly that many rays.\',\'Repeated headers within a frozen group are expected; cross-group stamps must differ.\']}\r\n result[\'continuous_pt_budget_validation\']=budget_results\r\n (out/\'group_validation.json\').write_text(json.dumps(result,indent=2));print(json.dumps({\'ok\':result[\'ok\'],\'groups\':len(groups),\'errors\':errors}));return 0 if result[\'ok\'] else 1\r\nif __name__==\'__main__\':raise SystemExit(main(sys.argv[1]))\r\n', 'sha256': '8348ce8c61b2e55a366e32e38380ced07854410f35ff9ce5f521370e2a4a3274'}}
